// Verify the shared secret (if set), then normalize the request.
const item = $input.first().json;
const body = item.body ?? item;
const headers = item.headers ?? {};
const need = $env.N8N_BANK_SECRET;
if (need && headers['x-trakr-secret'] !== need) {
  throw new Error('Invalid x-trakr-secret');
}
const SPORTS = ['swim', 'bike', 'run', 'strength'];
const ALL_PHASES = ['Base', 'Build', 'Peak', 'Taper'];
const sports = Array.isArray(body.sports) ? body.sports.filter((s) => SPORTS.includes(s)) : [];
if (!sports.length) throw new Error('No valid sports in request');
let perPhase = Number(body.perPhase);
if (!Number.isFinite(perPhase) || perPhase < 1) perPhase = 3;
if (perPhase > 20) perPhase = 20;
const phases = Array.isArray(body.phases) && body.phases.length
  ? body.phases.filter((p) => ALL_PHASES.includes(p))
  : ALL_PHASES;
return [{ json: { agencyId: body.agencyId, staffId: body.staffId, sports, perPhase, phases: phases.length ? phases : ALL_PHASES } }];

// The "head coach": turn the agency methodology into a directive per sport.
const p = $('Guard + normalize').first().json;
const methRow = $('Read methodology').first().json;
const methodology = methRow ? methRow.methodology : null;
const system = 'You are the head coach of an endurance training agency, building a library of reusable workouts that a specialist per sport will flesh out. Honor the agency methodology exactly. Output ONLY JSON, no prose, no markdown.';
const user =
  'Methodology (JSON, may be null): ' + JSON.stringify(methodology) + '\n' +
  'Sports to cover: ' + p.sports.join(', ') + '\n' +
  'Cycle phases: ' + p.phases.join(', ') + '\n' +
  'For EACH sport, write concise directives for that sport specialist: intensity distribution, the 2-3 signature session types, and how they progress across ' + p.phases.join('/') + '. ~5 sentences per sport.\n' +
  'Return a JSON object mapping each sport to its directive string, e.g. {"swim":"...","bike":"..."}.';
return [{ json: { llmBody: {
  model: 'gpt-4o',
  max_tokens: 1500,
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
} } }];

// Fan out: one task per sport, each carrying a ready OpenAI request for that
// sport's specialist. The specialist HTTP node runs once per item below.
const FENCE = String.fromCharCode(96, 96, 96);
// Tag vocabulary handed to the specialists — keeps a generated bank coherent
// instead of 40 spellings of "threshold". Mirrors lib/bank-tags.ts.
const SUGGESTED_TAGS = [
  'recovery','endurance','tempo','threshold','vo2max','anaerobic','sprint',
  'intervals','long','steady','pyramid','fartlek','negative-split','brick',
  'technique','drills','cadence','climbing','pacing','strength-endurance','test','race-simulation',
  'indoor','trainer','treadmill','track','hills','open-water','pool','gym',
  'hypertrophy','max-strength','power','core','mobility','plyometrics',
];
function parseJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  if (t.startsWith(FENCE)) { t = t.slice(t.indexOf('\n') + 1); const e = t.lastIndexOf(FENCE); if (e >= 0) t = t.slice(0, e); t = t.trim(); }
  return JSON.parse(t);
}
const p = $('Guard + normalize').first().json;
const resp = $input.first().json;
const text = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : '';
let briefs = {};
try { briefs = parseJson(text) || {}; } catch (e) { briefs = {}; }
const out = [];
for (const sport of p.sports) {
  const brief = briefs[sport] || ('Design ' + sport + ' sessions faithful to the methodology.');
  const total = p.perPhase * p.phases.length;
  const system = 'You are the ' + sport + ' specialist coach writing reusable ' + sport + ' workouts for an agency library. Follow the head coach directive and the methodology. EVERY workout must include a structure array of blocks. Output ONLY a JSON array, no prose, no markdown.';
  const user =
    'Head coach directive for ' + sport + ': ' + brief + '\n' +
    'Cycle phases: ' + p.phases.join(', ') + '\n' +
    'Produce ' + p.perPhase + ' ' + sport + ' workout(s) for EACH phase listed.\n' +
    'Each workout object: { "phase": one of ' + p.phases.join('|') + ', "title": short name, "description": 1-2 sentences, "duration_min": integer (whole session), "tss": integer estimate, "tags": array of 2-5 classification slugs, "structure": [{ "label": string, "duration_min": number — DECIMALS ALLOWED, 45 seconds is 0.75, "intensity": integer percent of threshold, "target": short string e.g. "Z2" or "CSS+3s", "note": optional string }] }.\n' +
    'EXPAND REPEATS into one block each. 8x45s uphill with jog-down recovery is SIXTEEN blocks (8 of 0.75min at the work intensity, each followed by its recovery block) — never one 20-minute block labelled "8x45s". The chart draws one bar per block, so a collapsed repeat renders as a single steady effort and the watch file loses the intervals entirely.\n' +
    'For "tags", classify the session FOCUS (never repeat the sport or the phase — those are stored separately). Prefer these slugs: ' + SUGGESTED_TAGS.join(', ') + '. Lowercase kebab-case; your own slug is fine if none fits.\n' +
    'Return a JSON array of all ' + total + ' workouts. No markdown.';
  out.push({ json: {
    sport, agencyId: p.agencyId, staffId: p.staffId,
    llmBody: { model: 'gpt-4o', max_tokens: 4096, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] },
  } });
}
return out;

// Parse each specialist's JSON array into individual draft rows. The specialist
// responses come back in the same order as the tasks, so index i lines up.
const FENCE = String.fromCharCode(96, 96, 96);
function parseJson(text) {
  if (!text) return null;
  let t = String(text).trim();
  if (t.startsWith(FENCE)) { t = t.slice(t.indexOf('\n') + 1); const e = t.lastIndexOf(FENCE); if (e >= 0) t = t.slice(0, e); t = t.trim(); }
  return JSON.parse(t);
}
// One tag, one spelling — mirrors normalizeTag() in the app/MCP. The DB must
// hold the canonical slug, because list_bank filters with tags @> [...].
const VOCAB = [
  'recovery','endurance','tempo','threshold','vo2max','anaerobic','sprint',
  'intervals','long','steady','pyramid','fartlek','negative-split','brick',
  'technique','drills','cadence','climbing','pacing','strength-endurance','test','race-simulation',
  'indoor','trainer','treadmill','track','hills','open-water','pool','gym',
  'hypertrophy','max-strength','power','core','mobility','plyometrics',
];
function normTags(raw) {
  if (!Array.isArray(raw)) return [];
  const seen = new Set();
  for (const t of raw) {
    const kebab = String(t).trim().toLowerCase().normalize('NFD')
      .replace(/\p{Diacritic}/gu, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40);
    if (!kebab) continue;
    const compact = kebab.replace(/-/g, '');
    const snapped = VOCAB.find((v) => v.replace(/-/g, '') === compact) || kebab;
    seen.add(snapped);
  }
  return Array.from(seen);
}
const ctxAll = $('Plan per-sport tasks').all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const ctx = (ctxAll[i] && ctxAll[i].json) || {};
  const resp = items[i].json;
  const text = resp && resp.choices && resp.choices[0] && resp.choices[0].message ? resp.choices[0].message.content : '';
  let arr = [];
  try { arr = parseJson(text) || []; } catch (e) { arr = []; }
  if (!Array.isArray(arr)) arr = [];
  for (const w of arr) {
    if (!w || !w.title) continue;
    out.push({ json: {
      agencyId: ctx.agencyId,
      staffId: ctx.staffId,
      sport: ctx.sport,
      phase: w.phase || null,
      title: String(w.title).slice(0, 200),
      description: w.description || null,
      duration_min: Number.isFinite(+w.duration_min) ? Math.round(+w.duration_min) : null,
      tss: Number.isFinite(+w.tss) ? Math.round(+w.tss) : null,
      structure: Array.isArray(w.structure) ? w.structure : null,
      tags: normTags(w.tags),
    } });
  }
}
return out;
